<script setup lang="ts">
import { computed, onUnmounted, ref } from 'vue'
import type { PartySession } from './usePartySession'
import type { QueueCommand } from './api'
import SongArtwork from './SongArtwork.vue'
import PartyIcon from './PartyIcon.vue'
const props = defineProps<{ session: PartySession; compact?: boolean }>()
const emit = defineEmits<{ confirm: [action: string]; correct: []; command: [action: string, fields?: Partial<QueueCommand>]; reaction: [kind: 'LIKE' | 'CLAP' | 'CHEER'] }>()
const snapshot = computed(() => props.session.state.snapshot), playback = computed(() => snapshot.value?.playback), current = computed(() => props.session.current.value)
const states: Record<string, string> = { IDLE: '已停止', PREPARING: '正在准备', BUFFERING: '正在缓冲', PLAYING: '正在唱', PAUSED: '已暂停', ENDED: '等待下一首', ERROR: '播放失败' }
const enabled = computed(() => props.session.state.online && snapshot.value?.tvOnline && snapshot.value?.queuePolicy === 'FAIR' && !props.session.state.busy && !props.session.state.pending && snapshot.value.status === 'ACTIVE')
const active = computed(() => playback.value && !['ENDED', 'IDLE', 'ERROR'].includes(playback.value.state) && !snapshot.value?.manualStopped)
const now = ref(Date.now()), draft = ref<number | null>(null)
let attempt = '', interval = setInterval(() => { now.value = Date.now() }, 1000)
onUnmounted(() => clearInterval(interval))
const position = computed(() => {
  const p = playback.value; if (!p) return 0
  const age = p.sampledAt && snapshot.value?.sampledAt ? Math.max(0, Date.parse(snapshot.value.sampledAt) - Date.parse(p.sampledAt)) : 0
  const elapsed = p.state === 'PLAYING' && snapshot.value?.tvOnline ? Math.max(0, now.value - props.session.state.receivedAt) + age : 0
  return Math.min(p.durationMs ?? Number.MAX_SAFE_INTEGER, (p.positionMs ?? 0) + elapsed)
})
function time(ms: number) { const seconds = Math.floor(Math.max(0, ms) / 1000); return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}` }
function preview(event: Event) { if (draft.value === null) attempt = playback.value?.attemptId ?? ''; draft.value = Number((event.target as HTMLInputElement).value) }
function seek() { if (draft.value !== null) emit('command', 'SEEK', { positionMs: draft.value, attemptId: attempt }); draft.value = null }
</script>
<template><section class="remote-panel" :class="{ compact }"><div class="tv-screen"><div class="tv-stamp"><PartyIcon name="tv" />客厅电视</div><span class="tv-status">{{ snapshot?.tvOnline ? (states[playback?.state ?? ''] || '等待开唱') : '电视离线' }}</span><SongArtwork v-if="current" :path="current.song.coverPath" :token="session.state.credential?.token" /><PartyIcon v-else class="idle-tv" name="tv" /><h3>{{ current?.song.title || '好歌，大家轮流唱' }}</h3><p>{{ current ? `${current.song.artists?.join(' / ') || '歌手未知'} · ${current.ownerName}点的` : session.waiting.value.length ? '已停止，点击开始继续队列' : '点上第一首，电视自动开唱' }}</p></div><div class="remote-body"><p v-if="snapshot?.queuePolicy !== 'FAIR'" class="inline-error">更新 TV 版本后，可使用全员遥控与自动开唱。</p><template v-if="!compact"><div class="seek-label"><span>{{ time(draft ?? position) }}</span><span>{{ playback?.durationMs ? time(playback.durationMs) : '总时长待电视回报' }}</span></div><input class="seek-range" type="range" min="0" :max="playback?.durationMs ?? 1" step="1000" :value="draft ?? position" aria-label="电视播放进度" :disabled="!enabled || !active || !playback?.durationMs || !snapshot?.capabilities?.includes('SEEK') || ['PREPARING', 'BUFFERING'].includes(playback?.state ?? '')" @input="preview" @change="seek"><div class="remote-main-controls"><button class="outline" :disabled="!enabled || !active" @click="emit('confirm', 'RESTART')"><PartyIcon name="restart" />重唱</button><button class="primary" :disabled="!enabled || (!active && !session.waiting.value.length)" @click="emit('command', !active ? 'START' : playback?.state === 'PAUSED' ? 'RESUME' : 'PAUSE')"><PartyIcon :name="active && playback?.state !== 'PAUSED' ? 'pause' : 'play'" />{{ !active ? '开始' : playback?.state === 'PAUSED' ? '继续' : '暂停' }}</button><button class="outline" :disabled="!enabled || !active" @click="emit('confirm', 'NEXT')"><PartyIcon name="next" />切歌</button></div><div class="role-controls"><div class="segmented" aria-label="播放音轨"><button :class="{ active: playback?.audioRole === 'original' }" :disabled="!enabled || !active || !snapshot?.capabilities?.includes('AUDIO_ROLE')" @click="emit('command', 'AUDIO_ROLE', { role: 'original' })">原唱</button><button :class="{ active: playback?.audioRole === 'backing' }" :disabled="!enabled || !active || !snapshot?.capabilities?.includes('AUDIO_ROLE')" @click="emit('command', 'AUDIO_ROLE', { role: 'backing' })">伴奏</button></div><button class="text-button" :disabled="!current" @click="emit('correct')">原伴不对？纠正</button></div></template><div v-else class="side-controls"><button class="outline" :disabled="!enabled || !active" @click="emit('command', playback?.state === 'PAUSED' ? 'RESUME' : 'PAUSE')"><PartyIcon :name="playback?.state === 'PAUSED' ? 'play' : 'pause'" />{{ playback?.state === 'PAUSED' ? '继续' : '暂停' }}</button><button class="outline" :disabled="!enabled || !active" @click="emit('confirm', 'NEXT')"><PartyIcon name="next" />切歌</button></div><div class="reaction-row"><button v-for="entry in ([['LIKE','like','点赞'],['CLAP','clap','鼓掌'],['CHEER','cheer','喝彩']] as const)" :key="entry[0]" class="reaction-btn" :disabled="!session.state.online || !snapshot?.tvOnline || !snapshot?.capabilities?.includes('REACTIONS')" @click="emit('reaction', entry[0])"><PartyIcon :name="entry[1]" />{{ entry[2] }}</button></div><p v-if="!compact" class="helper">所有在场亲友都能遥控。互动会在电视全屏显示约两秒，无音效。</p></div></section></template>
